use std::sync::Mutex;

struct Ledger { balance: Mutex<i64> }

impl Ledger {
    fn transfer(&self, cents: i64) {
        let mut guard = self.balance.lock().unwrap();  // acquire
        *guard += cents;                               // critical section = guard scope
    }                                                  // guard dropped: unlock
}

