use tokio::sync::Mutex;

struct Registry { conns: Mutex<Vec<Conn>> }

impl Registry {
    async fn add(&self, c: Conn) {
        let mut guard = self.conns.lock().await;  // awaits the lock, guard is Send
        guard.push(c);
        persist(&guard).await;                    // still locked here
    }
}
